    "namingConcept": "「タテヤマ」の名称は、山名を荷重の受け方・ピーク性能・足場の安定という工学的な比喩へ読み替えるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "重工系の標準設計群として、現場で壊れず予定通りに仕事を終えることを最初の評価軸に置いた。タテヤマはその中で実体弾射撃系列を担当し、要求仕様を曖昧にせず、用途を絞ることで実機の再現性を高めるという霧島重工の企業思想を、反動処理・追跡・装備制御をまとめ、実体弾兵装の命中と連続射撃を崩さないよう設計するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、反動処理・追跡・装備制御をまとめ、実体弾兵装の命中と連続射撃を崩さないよう設計すること。「実弾射撃の精度・制御・追跡を安定させる設計」という基本思想に加え、センサー系を系列固有の署名として一段強めている。反対に駆動系には意図的な余裕不足を残し、近接へ踏み込まれると設計余力を使いにくく、駆動や耐性の補強が課題になりやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
