    "namingConcept": "「コウヤ」の名称は、山名を荷重の受け方・ピーク性能・足場の安定という工学的な比喩へ読み替えるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
