    "summary": "誘導兵装系列。追跡・演算・AI判断を連携させ、ミサイルの誘導と発射判断を機体システム全体で支える。誘導系へ資源を割くぶん近接時の直接出力は伸びにくい",
    "concept": "スミレは誘導兵装系列。追跡・演算・AI判断を連携させ、ミサイルの誘導と発射判断を機体システム全体で支える。誘導系へ資源を割くぶん近接時の直接出力は伸びにくい。瑞穂産業の初期設計群の中では「誘導兵装系列 / 専門化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「スミレ」の名称は、花名を咲き方・季節適応・しなやかさ・更新の速さという運用上の性格へ置き換えるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "初期顧客の運用ログを大量に取り込み、同じ基本骨格でも使われ方に応じて性格を変えた。スミレはその中で誘導兵装系列を担当し、現場から戻る不満や成功例を次ロットへ反映し、机上の完成より使用後の完成度を重視するという瑞穂産業の企業思想を、追跡・演算・AI判断を連携させ、ミサイルの誘導と発射判断を機体システム全体で支えるという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、追跡・演算・AI判断を連携させ、ミサイルの誘導と発射判断を機体システム全体で支えること。「追跡・演算・AIを連携させ、ミサイル運用へ寄せる」という基本思想に加え、センサー系を系列固有の署名として一段強めている。反対に制御系には意図的な余裕不足を残し、誘導系へ資源を割くぶん近接時の直接出力は伸びにくい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「中盤型」の伸び方を前提に、センサー系かミサイル兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "誘導兵装系列 / 専門化群",
