    "concept": "スイショウは重攻撃系列。重量と熱負荷を受け入れてでも、大型兵装を安定して振り切れる出力・機関・姿勢保持を確保する。軽快さと情報更新は犠牲になりやすく、相手に主導権を取られると重さが露出する。剛岳工廠の初期設計群の中では「重攻撃系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
