    "developmentBackground": "過剰設計を商品価値に変えるため、各系列で「どこに余裕を積むか」を明確に分けた。スイショウはその中で重攻撃系列を担当し、余裕を重量ではなく性能資源と見なし、限界値より一段上の構造・熱・出力マージンを確保するという剛岳工廠の企業思想を、重量と熱負荷を受け入れてでも、大型兵装を安定して振り切れる出力・機関・姿勢保持を確保するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、重量と熱負荷を受け入れてでも、大型兵装を安定して振り切れる出力・機関・姿勢保持を確保すること。「出力・機関・耐性を高め、重兵装の正面性能を追求する」という基本思想に加え、出力系を系列固有の署名として一段強めている。反対に駆動系には意図的な余裕不足を残し、軽快さと情報更新は犠牲になりやすく、相手に主導権を取られると重さが露出する。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、出力系かハンマー・キャノン兵装を軸にすると個性が出やすい。カスタムは構造改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はEMP、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
