    "concept": "コクヨウは機関余力系列。発電・供給・冷却・熱容量を厚くし、他の性能が負荷で落ちない土台を作る。直接勝敗へ見えにくい能力へ資源を使うため、初見では総合評価以上に地味に映りやすい。剛岳工廠の初期設計群の中では「機関余力系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「コクヨウ」の名称は、鉱物名を硬度・結晶構造・熱容量・破断しにくさの設計記号として使うという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "過剰設計を商品価値に変えるため、各系列で「どこに余裕を積むか」を明確に分けた。コクヨウはその中で機関余力系列を担当し、余裕を重量ではなく性能資源と見なし、限界値より一段上の構造・熱・出力マージンを確保するという剛岳工廠の企業思想を、発電・供給・冷却・熱容量を厚くし、他の性能が負荷で落ちない土台を作るという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、発電・供給・冷却・熱容量を厚くし、他の性能が負荷で落ちない土台を作ること。「発電・供給・冷却に余裕を持たせ、兵装の土台を強くする」という基本思想に加え、機関系を系列固有の署名として一段強めている。反対に駆動系には意図的な余裕不足を残し、直接勝敗へ見えにくい能力へ資源を使うため、初見では総合評価以上に地味に映りやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
