    "concept": "メノウは高信頼標準系列。設計値に近い性能を毎回出すことを最優先し、信頼性と制御の再現性へ資源を回す。大当たり個体や極端なピーク性能は出にくい代わりに、計画通り育てやすい。剛岳工廠の初期設計群の中では「高信頼標準系列 / 用途分化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「メノウ」の名称は、鉱物名を硬度・結晶構造・熱容量・破断しにくさの設計記号として使うという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "過剰設計を商品価値に変えるため、各系列で「どこに余裕を積むか」を明確に分けた。メノウはその中で高信頼標準系列を担当し、余裕を重量ではなく性能資源と見なし、限界値より一段上の構造・熱・出力マージンを確保するという剛岳工廠の企業思想を、設計値に近い性能を毎回出すことを最優先し、信頼性と制御の再現性へ資源を回すという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、設計値に近い性能を毎回出すことを最優先し、信頼性と制御の再現性へ資源を回すこと。「性能の再現性と安定稼働を最優先する堅実設計」という基本思想に加え、制御系を系列固有の署名として一段強めている。反対にセンサー系には意図的な余裕不足を残し、大当たり個体や極端なピーク性能は出にくい代わりに、計画通り育てやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「完成品型」の伸び方を前提に、制御系か得意グループを軸にすると個性が出やすい。カスタムは精密改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装は特に固定されておらず、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "高信頼標準系列 / 用途分化群",
