    "namingConcept": "「キセキ」の名称は、鉱物名を硬度・結晶構造・熱容量・破断しにくさの設計記号として使うという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
