    "engineeringNotes": "設計の中心は、電力供給・熱処理・照準演算を連成させ、レーザーやビーム砲を安定した射撃システムとして成立させること。「エネルギー射撃の出力・収束・熱処理を重視する」という基本思想に加え、機関系を系列固有の署名として一段強めている。反対に駆動系には意図的な余裕不足を残し、機関への依存が大きく、冷却や供給が崩れると複数能力が同時に落ちやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、機関系かレーザー・ビームキャノン兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
