    "trainingNotes": "育成では「中盤型」の伸び方を前提に、演算系かEMP兵装を軸にすると個性が出やすい。カスタムは電子改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
