    "id": "yashima-fubuki",
    "legacyRefit": true,
    "summary": "複合近接系列。近接兵装の切替と姿勢遷移を一つの動作体系にまとめ、間合いの変化へ追従する。単一武器へ特化した系列より最大値は低いが、兵装変更を含む育成自由度が高い",
    "concept": "フブキは複合近接系列。近接兵装の切替と姿勢遷移を一つの動作体系にまとめ、間合いの変化へ追従する。単一武器へ特化した系列より最大値は低いが、兵装変更を含む育成自由度が高い。八洲重機の初期設計群の中では「複合近接系列 / 用途分化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「フブキ」の名称は、気象や自然現象の名を、急変・持続・視界・負荷変動への応答パターンとして解釈するという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "環境試験の結果を中心に設計され、単一性能より「崩れ方が穏やかであること」を評価した。フブキはその中で複合近接系列を担当し、得意条件だけでなく条件が崩れた後も任務を続けられることを重視するという八洲重機の企業思想を、近接兵装の切替と姿勢遷移を一つの動作体系にまとめ、間合いの変化へ追従するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、近接兵装の切替と姿勢遷移を一つの動作体系にまとめ、間合いの変化へ追従すること。「近接兵装を選ばず扱えるよう駆動・制御・出力を均衡させる」という基本思想に加え、駆動系を系列固有の署名として一段強めている。反対に機関系には意図的な余裕不足を残し、単一武器へ特化した系列より最大値は低いが、兵装変更を含む育成自由度が高い。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「中盤型」の伸び方を前提に、駆動系かブレード・ハンマー・ランス・ビームブレード兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はキャノン、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
