    "concept": "ハルカゼは高機動系列。加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙う。耐性や持続出力に余裕が少なく、長い消耗戦では得意な速度を維持しにくい。八洲重機の初期設計群の中では「高機動系列 / 専門化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ハルカゼ」の名称は、気象や自然現象の名を、急変・持続・視界・負荷変動への応答パターンとして解釈するという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "環境試験の結果を中心に設計され、単一性能より「崩れ方が穏やかであること」を評価した。ハルカゼはその中で高機動系列を担当し、得意条件だけでなく条件が崩れた後も任務を続けられることを重視するという八洲重機の企業思想を、加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙うという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙うこと。「駆動・反応・制御を重視した高速設計」という基本思想に加え、駆動系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、耐性や持続出力に余裕が少なく、長い消耗戦では得意な速度を維持しにくい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「早熟」の伸び方を前提に、駆動系かブレード・ランス・ビームブレード兵装を軸にすると個性が出やすい。カスタムは高モジュール適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はキャノン・ビームキャノン、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "高機動系列 / 専門化群",
