    "namingConcept": "「ツユ」の名称は、気象や自然現象の名を、急変・持続・視界・負荷変動への応答パターンとして解釈するという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
