    "concept": "リュウセイは基幹汎用系列。一つの能力で勝つのではなく、出力・駆動・制御・機関・情報系の接続を崩さないことを優先する。極端な相手へ一点で競るのは苦手だが、育成方針を途中で変えても破綻しにくい。北辰精機の初期設計群の中では「基幹汎用系列 / 用途分化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
