    "concept": "ハクチョウは適応・改修系列。初期状態を完成形とせず、弱点補強や運用変更を受け止められる余白を骨格と制御に残す。初期値だけを見ると平凡になりやすいが、育成と改修の方向を後から選びやすい。北辰精機の初期設計群の中では「適応・改修系列 / 専門化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ハクチョウ」の名称は、天体名を軌道・周期・観測精度・位置決定の再現性へ結び付けるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
