    "engineeringNotes": "設計の中心は、初期状態を完成形とせず、弱点補強や運用変更を受け止められる余白を骨格と制御に残すこと。「一部特化を避け、複数の条件で最低性能を落としにくい設計」という基本思想に加え、機関系を系列固有の署名として一段強めている。反対に駆動系には意図的な余裕不足を残し、初期値だけを見ると平凡になりやすいが、育成と改修の方向を後から選びやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
