    "trainingNotes": "育成では「均等成長」の伸び方を前提に、出力系か得意グループを軸にすると個性が出やすい。カスタムは標準適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装は特に固定されておらず、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "基幹汎用系列 / 専門化群",
