    "concept": "ショウジョウは高出力系列。瞬間出力と過負荷領域を積極的に使い、短時間で能力差を作ることを狙う。熱・信頼性・持続性との交換が明確で、扱いを誤ると数値ほど安定して勝てない。東雲電子技研の初期設計群の中では「高出力系列 / 初期技術展開群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ショウジョウ」の名称は、色名を波長・階調・識別・情報の見せ方という電子系の性格へ転写するという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
