    "id": "amagi-taka",
    "legacyRefit": true,
    "summary": "エネルギー近接系列。近接運動と高密度電力供給を同期させ、ビームブレードの出力を動作中も維持する。機関・制御・駆動を同時に要求するため、どこか一つが遅れると完成度が落ちやすい",
    "concept": "タカはエネルギー近接系列。近接運動と高密度電力供給を同期させ、ビームブレードの出力を動作中も維持する。機関・制御・駆動を同時に要求するため、どこか一つが遅れると完成度が落ちやすい。天城機工の初期設計群の中では「エネルギー近接系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「タカ」の名称は、動物名を加速の仕方・止まり方・重心移動・獲物への詰め方という運動様式へ落とし込むという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "モーションログを設計資料として扱い、同じ出力でも動きの印象が明確に変わる系列を揃えた。タカはその中でエネルギー近接系列を担当し、最高速度よりも「どう動く機械か」を先に決め、その性格に合わせて駆動と制御を組むという天城機工の企業思想を、近接運動と高密度電力供給を同期させ、ビームブレードの出力を動作中も維持するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、近接運動と高密度電力供給を同期させ、ビームブレードの出力を動作中も維持すること。「ビームブレード運用を軸に出力・制御・機関を高める」という基本思想に加え、制御系を系列固有の署名として一段強めている。反対にセンサー系には意図的な余裕不足を残し、機関・制御・駆動を同時に要求するため、どこか一つが遅れると完成度が落ちやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「中盤型」の伸び方を前提に、制御系かビームブレード兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はキャノン、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
