    "concept": "ツルは実体弾射撃系列。反動処理・追跡・装備制御をまとめ、実体弾兵装の命中と連続射撃を崩さないよう設計する。近接へ踏み込まれると設計余力を使いにくく、駆動や耐性の補強が課題になりやすい。天城機工の初期設計群の中では「実体弾射撃系列 / 用途分化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ツル」の名称は、動物名を加速の仕方・止まり方・重心移動・獲物への詰め方という運動様式へ落とし込むという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "モーションログを設計資料として扱い、同じ出力でも動きの印象が明確に変わる系列を揃えた。ツルはその中で実体弾射撃系列を担当し、最高速度よりも「どう動く機械か」を先に決め、その性格に合わせて駆動と制御を組むという天城機工の企業思想を、反動処理・追跡・装備制御をまとめ、実体弾兵装の命中と連続射撃を崩さないよう設計するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、反動処理・追跡・装備制御をまとめ、実体弾兵装の命中と連続射撃を崩さないよう設計すること。「実弾射撃の精度・制御・追跡を安定させる設計」という基本思想に加え、センサー系を系列固有の署名として一段強めている。反対に駆動系には意図的な余裕不足を残し、近接へ踏み込まれると設計余力を使いにくく、駆動や耐性の補強が課題になりやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、センサー系かライフル・マシンガン・キャノン兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はビームブレード、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "実体弾射撃系列 / 用途分化群",
