    "concept": "ヤマタは遠距離エネルギー系列。電力供給・熱処理・照準演算を連成させ、レーザーやビーム砲を安定した射撃システムとして成立させる。機関への依存が大きく、冷却や供給が崩れると複数能力が同時に落ちやすい。神代技研の初期設計群の中では「遠距離エネルギー系列 / 用途分化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ヤマタ」の名称は、神話名を役割・象徴・逸話を既存規格への疑問として読み替えるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
