    "concept": "アイリスは適応・改修系列。初期状態を完成形とせず、弱点補強や運用変更を受け止められる余白を骨格と制御に残す。初期値だけを見ると平凡になりやすいが、育成と改修の方向を後から選びやすい。ランカスター・ダイナミクスの初期設計群の中では「適応・改修系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「アイリス」の名称は、花名を見た目ではなく市場で伝わりやすい商品性と用途イメージへ変換するという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
