    "namingConcept": "「ヴァイオレット」の名称は、花名を見た目ではなく市場で伝わりやすい商品性と用途イメージへ変換するという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
