    "developmentBackground": "初期商品群として市場セグメントを細かく切り分け、似た性能でも買う理由が違うよう構成した。カメリアはその中で複合射撃系列を担当し、性能を製品として成立させるため、顧客層・価格帯・用途を先に定義して設計を絞るというランカスター・ダイナミクスの企業思想を、複数の遠距離兵装を切り替えても照準系と姿勢制御を共有できるよう統合するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、複数の遠距離兵装を切り替えても照準系と姿勢制御を共有できるよう統合すること。「実弾・エネルギー双方の射撃兵装へ対応する汎用射撃設計」という基本思想に加え、制御系を系列固有の署名として一段強めている。反対にAI系には意図的な余裕不足を残し、一種類へ専用化した機体ほどのピークは持たないが、相手に合わせて兵装を変えやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
