    "concept": "ピオニーは遠距離エネルギー系列。電力供給・熱処理・照準演算を連成させ、レーザーやビーム砲を安定した射撃システムとして成立させる。機関への依存が大きく、冷却や供給が崩れると複数能力が同時に落ちやすい。ランカスター・ダイナミクスの初期設計群の中では「遠距離エネルギー系列 / 専門化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ピオニー」の名称は、花名を見た目ではなく市場で伝わりやすい商品性と用途イメージへ変換するという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "初期商品群として市場セグメントを細かく切り分け、似た性能でも買う理由が違うよう構成した。ピオニーはその中で遠距離エネルギー系列を担当し、性能を製品として成立させるため、顧客層・価格帯・用途を先に定義して設計を絞るというランカスター・ダイナミクスの企業思想を、電力供給・熱処理・照準演算を連成させ、レーザーやビーム砲を安定した射撃システムとして成立させるという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、電力供給・熱処理・照準演算を連成させ、レーザーやビーム砲を安定した射撃システムとして成立させること。「エネルギー射撃の出力・収束・熱処理を重視する」という基本思想に加え、機関系を系列固有の署名として一段強めている。反対にAI系には意図的な余裕不足を残し、機関への依存が大きく、冷却や供給が崩れると複数能力が同時に落ちやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、機関系かレーザー・ビームキャノン兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
