    "id": "steinwald-everest",
    "legacyRefit": true,
    "summary": "重攻撃系列。重量と熱負荷を受け入れてでも、大型兵装を安定して振り切れる出力・機関・姿勢保持を確保する。軽快さと情報更新は犠牲になりやすく、相手に主導権を取られると重さが露出する",
    "concept": "エベレストは重攻撃系列。重量と熱負荷を受け入れてでも、大型兵装を安定して振り切れる出力・機関・姿勢保持を確保する。軽快さと情報更新は犠牲になりやすく、相手に主導権を取られると重さが露出する。シュタインヴァルト・インダストリーズの初期設計群の中では「重攻撃系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「エベレスト」の名称は、山名を骨格・荷重経路・重心位置・機関配置という物理構造の比喩として扱うという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "古典的な構造設計を現代戦闘機械へ適用し、ソフトが止まっても成立する基礎挙動を狙った。エベレストはその中で重攻撃系列を担当し、電子補正で隠す前に、機械そのものの姿勢と重量配分を正しくするというシュタインヴァルト・インダストリーズの企業思想を、重量と熱負荷を受け入れてでも、大型兵装を安定して振り切れる出力・機関・姿勢保持を確保するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、重量と熱負荷を受け入れてでも、大型兵装を安定して振り切れる出力・機関・姿勢保持を確保すること。「出力・機関・耐性を高め、重兵装の正面性能を追求する」という基本思想に加え、出力系を系列固有の署名として一段強めている。反対に駆動系には意図的な余裕不足を残し、軽快さと情報更新は犠牲になりやすく、相手に主導権を取られると重さが露出する。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、出力系かハンマー・キャノン兵装を軸にすると個性が出やすい。カスタムは構造改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はEMP、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
