    "concept": "デナリは機関余力系列。発電・供給・冷却・熱容量を厚くし、他の性能が負荷で落ちない土台を作る。直接勝敗へ見えにくい能力へ資源を使うため、初見では総合評価以上に地味に映りやすい。シュタインヴァルト・インダストリーズの初期設計群の中では「機関余力系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「デナリ」の名称は、山名を骨格・荷重経路・重心位置・機関配置という物理構造の比喩として扱うという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "古典的な構造設計を現代戦闘機械へ適用し、ソフトが止まっても成立する基礎挙動を狙った。デナリはその中で機関余力系列を担当し、電子補正で隠す前に、機械そのものの姿勢と重量配分を正しくするというシュタインヴァルト・インダストリーズの企業思想を、発電・供給・冷却・熱容量を厚くし、他の性能が負荷で落ちない土台を作るという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、発電・供給・冷却・熱容量を厚くし、他の性能が負荷で落ちない土台を作ること。「発電・供給・冷却に余裕を持たせ、兵装の土台を強くする」という基本思想に加え、機関系を系列固有の署名として一段強めている。反対に駆動系には意図的な余裕不足を残し、直接勝敗へ見えにくい能力へ資源を使うため、初見では総合評価以上に地味に映りやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
