    "summary": "物理近接系列。接触時の姿勢・瞬間出力・駆動応答をまとめ、刃・槌・槍の一撃を機体全体で支える。観測や遠距離処理は優先度が低く、接近できない相手への回答を育成で用意する必要がある",
    "concept": "キリマンジャロは物理近接系列。接触時の姿勢・瞬間出力・駆動応答をまとめ、刃・槌・槍の一撃を機体全体で支える。観測や遠距離処理は優先度が低く、接近できない相手への回答を育成で用意する必要がある。シュタインヴァルト・インダストリーズの初期設計群の中では「物理近接系列 / 用途分化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「キリマンジャロ」の名称は、山名を骨格・荷重経路・重心位置・機関配置という物理構造の比喩として扱うという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "古典的な構造設計を現代戦闘機械へ適用し、ソフトが止まっても成立する基礎挙動を狙った。キリマンジャロはその中で物理近接系列を担当し、電子補正で隠す前に、機械そのものの姿勢と重量配分を正しくするというシュタインヴァルト・インダストリーズの企業思想を、接触時の姿勢・瞬間出力・駆動応答をまとめ、刃・槌・槍の一撃を機体全体で支えるという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、接触時の姿勢・瞬間出力・駆動応答をまとめ、刃・槌・槍の一撃を機体全体で支えること。「物理近接兵装を扱うための出力・駆動・制御を強化」という基本思想に加え、出力系を系列固有の署名として一段強めている。反対にセンサー系には意図的な余裕不足を残し、観測や遠距離処理は優先度が低く、接近できない相手への回答を育成で用意する必要がある。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「早熟」の伸び方を前提に、出力系かブレード・ハンマー・ランス兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はビームキャノン、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
