    "namingConcept": "「アンデス」の名称は、山名を骨格・荷重経路・重心位置・機関配置という物理構造の比喩として扱うという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "古典的な構造設計を現代戦闘機械へ適用し、ソフトが止まっても成立する基礎挙動を狙った。アンデスはその中で高精度系列を担当し、電子補正で隠す前に、機械そのものの姿勢と重量配分を正しくするというシュタインヴァルト・インダストリーズの企業思想を、誤差を小さくすることに特化し、センサー・制御・演算のズレを詰めて兵装精度を引き上げるという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、誤差を小さくすることに特化し、センサー・制御・演算のズレを詰めて兵装精度を引き上げること。「制御・センサー・演算を揃え、誤差の少ない戦闘を志向する」という基本思想に加え、制御系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、ピーク出力や乱戦対応より再現性を優先するため、想定外の押し合いでは力負けしやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「完成品型」の伸び方を前提に、制御系かライフル・レーザー兵装を軸にすると個性が出やすい。カスタムは精密改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "高精度系列 / 専門化群",
