    "concept": "アルタイは適応・改修系列。初期状態を完成形とせず、弱点補強や運用変更を受け止められる余白を骨格と制御に残す。初期値だけを見ると平凡になりやすいが、育成と改修の方向を後から選びやすい。シュタインヴァルト・インダストリーズの初期設計群の中では「適応・改修系列 / 専門化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「アルタイ」の名称は、山名を骨格・荷重経路・重心位置・機関配置という物理構造の比喩として扱うという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "古典的な構造設計を現代戦闘機械へ適用し、ソフトが止まっても成立する基礎挙動を狙った。アルタイはその中で適応・改修系列を担当し、電子補正で隠す前に、機械そのものの姿勢と重量配分を正しくするというシュタインヴァルト・インダストリーズの企業思想を、初期状態を完成形とせず、弱点補強や運用変更を受け止められる余白を骨格と制御に残すという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、初期状態を完成形とせず、弱点補強や運用変更を受け止められる余白を骨格と制御に残すこと。「一部特化を避け、複数の条件で最低性能を落としにくい設計」という基本思想に加え、AI系を系列固有の署名として一段強めている。反対に駆動系には意図的な余裕不足を残し、初期値だけを見ると平凡になりやすいが、育成と改修の方向を後から選びやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「弱点補正」の伸び方を前提に、AI系か得意グループを軸にすると個性が出やすい。カスタムは高モジュール適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装は特に固定されておらず、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
