    "namingConcept": "「スカーレット」の名称は、色名を単独の色ではなく隣り合う色との関係や混色のような相互作用へ結び付けるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "統合制御の実証系列として、出力・駆動・情報系をペアで設計する思想を確立した。スカーレットはその中で適応・改修系列を担当し、一つの突出値より、複数機構が互いの欠点を補って総合性能を上げることを狙うというクロムウェル・システムズの企業思想を、初期状態を完成形とせず、弱点補強や運用変更を受け止められる余白を骨格と制御に残すという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、初期状態を完成形とせず、弱点補強や運用変更を受け止められる余白を骨格と制御に残すこと。「一部特化を避け、複数の条件で最低性能を落としにくい設計」という基本思想に加え、AI系を系列固有の署名として一段強めている。反対に制御系には意図的な余裕不足を残し、初期値だけを見ると平凡になりやすいが、育成と改修の方向を後から選びやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「弱点補正」の伸び方を前提に、AI系か得意グループを軸にすると個性が出やすい。カスタムは高モジュール適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装は特に固定されておらず、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "適応・改修系列 / 初期主力群",
