    "namingConcept": "「コバルト」の名称は、色名を単独の色ではなく隣り合う色との関係や混色のような相互作用へ結び付けるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "統合制御の実証系列として、出力・駆動・情報系をペアで設計する思想を確立した。コバルトはその中で複合射撃系列を担当し、一つの突出値より、複数機構が互いの欠点を補って総合性能を上げることを狙うというクロムウェル・システムズの企業思想を、複数の遠距離兵装を切り替えても照準系と姿勢制御を共有できるよう統合するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、複数の遠距離兵装を切り替えても照準系と姿勢制御を共有できるよう統合すること。「実弾・エネルギー双方の射撃兵装へ対応する汎用射撃設計」という基本思想に加え、センサー系を系列固有の署名として一段強めている。反対にAI系には意図的な余裕不足を残し、一種類へ専用化した機体ほどのピークは持たないが、相手に合わせて兵装を変えやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、センサー系かライフル・マシンガン・キャノン・レーザー・ビームキャノン兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
