    "engineeringNotes": "設計の中心は、反動処理・追跡・装備制御をまとめ、実体弾兵装の命中と連続射撃を崩さないよう設計すること。「実弾射撃の精度・制御・追跡を安定させる設計」という基本思想に加え、センサー系を系列固有の署名として一段強めている。反対に機関系には意図的な余裕不足を残し、近接へ踏み込まれると設計余力を使いにくく、駆動や耐性の補強が課題になりやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、センサー系かライフル・マシンガン・キャノン兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はビームブレード、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
