    "concept": "アクアは耐環境・生存系列。耐性・機関・制御の余裕を積み、苦手条件を踏んでも性能崩壊しにくくする。攻撃能力への直接投資が少なく、勝ち筋を作るには兵装適性か出力を後から伸ばしたい。クロムウェル・システムズの初期設計群の中では「耐環境・生存系列 / 初期技術展開群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
