    "summary": "高精度系列。誤差を小さくすることに特化し、センサー・制御・演算のズレを詰めて兵装精度を引き上げる。ピーク出力や乱戦対応より再現性を優先するため、想定外の押し合いでは力負けしやすい",
    "concept": "ガーネットは高精度系列。誤差を小さくすることに特化し、センサー・制御・演算のズレを詰めて兵装精度を引き上げる。ピーク出力や乱戦対応より再現性を優先するため、想定外の押し合いでは力負けしやすい。レニウム・ワークスの初期設計群の中では「高精度系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ガーネット」の名称は、鉱物名を希少性・加工難度・物性の尖りをそのまま機体の個性に変えるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "特殊素材と加工法のショーケースとして始まり、少量でも明確な技術価値を持つ系列を揃えた。ガーネットはその中で高精度系列を担当し、量産しにくい工程でも代替できない性能が得られるなら製品として成立させるというレニウム・ワークスの企業思想を、誤差を小さくすることに特化し、センサー・制御・演算のズレを詰めて兵装精度を引き上げるという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、誤差を小さくすることに特化し、センサー・制御・演算のズレを詰めて兵装精度を引き上げること。「制御・センサー・演算を揃え、誤差の少ない戦闘を志向する」という基本思想に加え、センサー系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、ピーク出力や乱戦対応より再現性を優先するため、想定外の押し合いでは力負けしやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
