    "concept": "トパーズは精密制御系列。兵装と機体運動を細かく同期させ、数値以上に「狙った動作を外さない」ことを重視する。粗い高出力運用には向かず、強みを活かすには制御・精度系を伸ばす育成が必要になる。レニウム・ワークスの初期設計群の中では「精密制御系列 / 用途分化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「トパーズ」の名称は、鉱物名を希少性・加工難度・物性の尖りをそのまま機体の個性に変えるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "特殊素材と加工法のショーケースとして始まり、少量でも明確な技術価値を持つ系列を揃えた。トパーズはその中で精密制御系列を担当し、量産しにくい工程でも代替できない性能が得られるなら製品として成立させるというレニウム・ワークスの企業思想を、兵装と機体運動を細かく同期させ、数値以上に「狙った動作を外さない」ことを重視するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、兵装と機体運動を細かく同期させ、数値以上に「狙った動作を外さない」ことを重視すること。「姿勢・装備・微細制御を軸に、武装を正確に扱う設計」という基本思想に加え、制御系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、粗い高出力運用には向かず、強みを活かすには制御・精度系を伸ばす育成が必要になる。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、制御系かライフル・レーザー・ランス兵装を軸にすると個性が出やすい。カスタムは精密改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "精密制御系列 / 用途分化群",
