    "namingConcept": "「オブシディアン」の名称は、鉱物名を希少性・加工難度・物性の尖りをそのまま機体の個性に変えるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
