    "engineeringNotes": "設計の中心は、近接兵装の切替と姿勢遷移を一つの動作体系にまとめ、間合いの変化へ追従すること。「近接兵装を選ばず扱えるよう駆動・制御・出力を均衡させる」という基本思想に加え、駆動系を系列固有の署名として一段強めている。反対にAI系には意図的な余裕不足を残し、単一武器へ特化した系列より最大値は低いが、兵装変更を含む育成自由度が高い。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「中盤型」の伸び方を前提に、駆動系かブレード・ハンマー・ランス・ビームブレード兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はキャノン、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
