    "concept": "ヴァイパーは観測系列。探知・識別・追跡・情報更新を早め、相手の状態を先に正しく把握することを狙う。情報を取るだけでは勝てないため、取得した優位を使う兵装かAI育成が必要になる。ホーソーン・ロボティクスの初期設計群の中では「観測系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ヴァイパー」の名称は、動物名を身体能力ではなく狩り方・警戒・群れ方・逃げ方といった行動哲学へ落とし込むという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
