    "engineeringNotes": "設計の中心は、探知・識別・追跡・情報更新を早め、相手の状態を先に正しく把握することを狙うこと。「探知・追跡・情報更新を優先する観測能力重視の設計」という基本思想に加え、センサー系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、情報を取るだけでは勝てないため、取得した優位を使う兵装かAI育成が必要になる。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
