    "legacyRefit": true,
    "summary": "高機動系列。加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙う。耐性や持続出力に余裕が少なく、長い消耗戦では得意な速度を維持しにくい",
    "concept": "コヨーテは高機動系列。加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙う。耐性や持続出力に余裕が少なく、長い消耗戦では得意な速度を維持しにくい。ホーソーン・ロボティクスの初期設計群の中では「高機動系列 / 用途分化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「コヨーテ」の名称は、動物名を身体能力ではなく狩り方・警戒・群れ方・逃げ方といった行動哲学へ落とし込むという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "自律行動研究の初期成果を製品化し、同じ命令でも選ぶ行動が違う系列を意図的に作った。コヨーテはその中で高機動系列を担当し、命令への反応だけでなく、状況をどう解釈して何を優先するかをAIの性格として設計するというホーソーン・ロボティクスの企業思想を、加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙うという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙うこと。「駆動・反応・制御を重視した高速設計」という基本思想に加え、駆動系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、耐性や持続出力に余裕が少なく、長い消耗戦では得意な速度を維持しにくい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「早熟」の伸び方を前提に、駆動系かブレード・ランス・ビームブレード兵装を軸にすると個性が出やすい。カスタムは高モジュール適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はキャノン・ビームキャノン、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
