    "summary": "高精度系列。誤差を小さくすることに特化し、センサー・制御・演算のズレを詰めて兵装精度を引き上げる。ピーク出力や乱戦対応より再現性を優先するため、想定外の押し合いでは力負けしやすい",
    "concept": "バイソンは高精度系列。誤差を小さくすることに特化し、センサー・制御・演算のズレを詰めて兵装精度を引き上げる。ピーク出力や乱戦対応より再現性を優先するため、想定外の押し合いでは力負けしやすい。ホーソーン・ロボティクスの初期設計群の中では「高精度系列 / 専門化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「バイソン」の名称は、動物名を身体能力ではなく狩り方・警戒・群れ方・逃げ方といった行動哲学へ落とし込むという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "自律行動研究の初期成果を製品化し、同じ命令でも選ぶ行動が違う系列を意図的に作った。バイソンはその中で高精度系列を担当し、命令への反応だけでなく、状況をどう解釈して何を優先するかをAIの性格として設計するというホーソーン・ロボティクスの企業思想を、誤差を小さくすることに特化し、センサー・制御・演算のズレを詰めて兵装精度を引き上げるという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、誤差を小さくすることに特化し、センサー・制御・演算のズレを詰めて兵装精度を引き上げること。「制御・センサー・演算を揃え、誤差の少ない戦闘を志向する」という基本思想に加え、制御系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、ピーク出力や乱戦対応より再現性を優先するため、想定外の押し合いでは力負けしやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
