    "namingConcept": "「イーグル」の名称は、動物名を身体能力ではなく狩り方・警戒・群れ方・逃げ方といった行動哲学へ落とし込むという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "自律行動研究の初期成果を製品化し、同じ命令でも選ぶ行動が違う系列を意図的に作った。イーグルはその中で耐環境・生存系列を担当し、命令への反応だけでなく、状況をどう解釈して何を優先するかをAIの性格として設計するというホーソーン・ロボティクスの企業思想を、耐性・機関・制御の余裕を積み、苦手条件を踏んでも性能崩壊しにくくするという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
