    "concept": "スコーピオンは物理近接系列。接触時の姿勢・瞬間出力・駆動応答をまとめ、刃・槌・槍の一撃を機体全体で支える。観測や遠距離処理は優先度が低く、接近できない相手への回答を育成で用意する必要がある。ホーソーン・ロボティクスの初期設計群の中では「物理近接系列 / 初期技術展開群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「スコーピオン」の名称は、動物名を身体能力ではなく狩り方・警戒・群れ方・逃げ方といった行動哲学へ落とし込むという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "自律行動研究の初期成果を製品化し、同じ命令でも選ぶ行動が違う系列を意図的に作った。スコーピオンはその中で物理近接系列を担当し、命令への反応だけでなく、状況をどう解釈して何を優先するかをAIの性格として設計するというホーソーン・ロボティクスの企業思想を、接触時の姿勢・瞬間出力・駆動応答をまとめ、刃・槌・槍の一撃を機体全体で支えるという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、接触時の姿勢・瞬間出力・駆動応答をまとめ、刃・槌・槍の一撃を機体全体で支えること。「物理近接兵装を扱うための出力・駆動・制御を強化」という基本思想に加え、駆動系を系列固有の署名として一段強めている。反対にセンサー系には意図的な余裕不足を残し、観測や遠距離処理は優先度が低く、接近できない相手への回答を育成で用意する必要がある。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「早熟」の伸び方を前提に、駆動系かブレード・ハンマー・ランス兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はビームキャノン、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "物理近接系列 / 初期技術展開群",
