    "concept": "アヌビスは遠距離エネルギー系列。電力供給・熱処理・照準演算を連成させ、レーザーやビーム砲を安定した射撃システムとして成立させる。機関への依存が大きく、冷却や供給が崩れると複数能力が同時に落ちやすい。アルカディア・テクノロジーズの初期設計群の中では「遠距離エネルギー系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「アヌビス」の名称は、神話名を神格や英雄の理想像を一つの性能目標として具体化するという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "各系列に「こうあるべき」という完成像を一つ置き、多少の無理をしてでもそこへ寄せた。アヌビスはその中で遠距離エネルギー系列を担当し、現実の制約から妥協点を探すのではなく、先に理想形を定義して技術を追いつかせるというアルカディア・テクノロジーズの企業思想を、電力供給・熱処理・照準演算を連成させ、レーザーやビーム砲を安定した射撃システムとして成立させるという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、電力供給・熱処理・照準演算を連成させ、レーザーやビーム砲を安定した射撃システムとして成立させること。「エネルギー射撃の出力・収束・熱処理を重視する」という基本思想に加え、センサー系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、機関への依存が大きく、冷却や供給が崩れると複数能力が同時に落ちやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、センサー系かレーザー・ビームキャノン兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "遠距離エネルギー系列 / 初期主力群",
