    "legacyRefit": true,
    "summary": "エネルギー近接系列。近接運動と高密度電力供給を同期させ、ビームブレードの出力を動作中も維持する。機関・制御・駆動を同時に要求するため、どこか一つが遅れると完成度が落ちやすい",
    "concept": "ホルスはエネルギー近接系列。近接運動と高密度電力供給を同期させ、ビームブレードの出力を動作中も維持する。機関・制御・駆動を同時に要求するため、どこか一つが遅れると完成度が落ちやすい。アルカディア・テクノロジーズの初期設計群の中では「エネルギー近接系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ホルス」の名称は、神話名を神格や英雄の理想像を一つの性能目標として具体化するという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
