    "namingConcept": "「アポロン」の名称は、神話名を神格や英雄の理想像を一つの性能目標として具体化するという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "各系列に「こうあるべき」という完成像を一つ置き、多少の無理をしてでもそこへ寄せた。アポロンはその中で演算中枢系列を担当し、現実の制約から妥協点を探すのではなく、先に理想形を定義して技術を追いつかせるというアルカディア・テクノロジーズの企業思想を、並列処理・情報統合・演算効率を厚くし、複数の判断やセンサー情報を同時に処理するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、並列処理・情報統合・演算効率を厚くし、複数の判断やセンサー情報を同時に処理すること。「処理能力と情報統合へ資源を集中した演算中心設計」という基本思想に加え、演算系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、演算能力が高くても駆動や機関が追いつかなければ結果へ変換できず、育成の噛み合わせが重要。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「晩成」の伸び方を前提に、演算系かEMP・ドローン・ミサイル兵装を軸にすると個性が出やすい。カスタムは電子改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "演算中枢系列 / 用途分化群",
