    "concept": "ペルセウスは精密制御系列。兵装と機体運動を細かく同期させ、数値以上に「狙った動作を外さない」ことを重視する。粗い高出力運用には向かず、強みを活かすには制御・精度系を伸ばす育成が必要になる。アルカディア・テクノロジーズの初期設計群の中では「精密制御系列 / 専門化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ペルセウス」の名称は、神話名を神格や英雄の理想像を一つの性能目標として具体化するという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
