    "concept": "シリウスは高精度系列。誤差を小さくすることに特化し、センサー・制御・演算のズレを詰めて兵装精度を引き上げる。ピーク出力や乱戦対応より再現性を優先するため、想定外の押し合いでは力負けしやすい。ソルベルグ・エンジニアリングの初期設計群の中では「高精度系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「シリウス」の名称は、天体名を軌道・周期・光度のように予測可能な挙動モデルへ対応させるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
