    "concept": "スピカは電子戦系列。電磁妨害を兵装単体ではなくセンサー・演算・判断系と組み合わせて運用する。物理的な押し合いには強くなく、相手の情報系へ干渉できない局面では得意分野が薄れる。ソルベルグ・エンジニアリングの初期設計群の中では「電子戦系列 / 用途分化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「スピカ」の名称は、天体名を軌道・周期・光度のように予測可能な挙動モデルへ対応させるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "大量の仮想試験から設計を絞り、実機がモデルから外れにくい系列を基準として整備した。スピカはその中で電子戦系列を担当し、最高値ではなく性能分布まで予測できることを品質とみなし、シミュレーションで設計域を決めるというソルベルグ・エンジニアリングの企業思想を、電磁妨害を兵装単体ではなくセンサー・演算・判断系と組み合わせて運用するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、電磁妨害を兵装単体ではなくセンサー・演算・判断系と組み合わせて運用すること。「演算・センサー・AIを電子攻撃へ最適化する」という基本思想に加え、演算系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、物理的な押し合いには強くなく、相手の情報系へ干渉できない局面では得意分野が薄れる。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「中盤型」の伸び方を前提に、演算系かEMP兵装を軸にすると個性が出やすい。カスタムは電子改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "電子戦系列 / 用途分化群",
