    "concept": "アンタレスは戦術AI系列。状況判断・予測・リスク判断を優先し、数値差が小さい局面で選択の質を上げる。機体ハードの余裕は平均的になりやすく、AIだけ伸ばしても土台の弱さは補えない。ソルベルグ・エンジニアリングの初期設計群の中では「戦術AI系列 / 用途分化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「アンタレス」の名称は、天体名を軌道・周期・光度のように予測可能な挙動モデルへ対応させるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "大量の仮想試験から設計を絞り、実機がモデルから外れにくい系列を基準として整備した。アンタレスはその中で戦術AI系列を担当し、最高値ではなく性能分布まで予測できることを品質とみなし、シミュレーションで設計域を決めるというソルベルグ・エンジニアリングの企業思想を、状況判断・予測・リスク判断を優先し、数値差が小さい局面で選択の質を上げるという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、状況判断・予測・リスク判断を優先し、数値差が小さい局面で選択の質を上げること。「判断・予測・戦術選択を中心に戦闘AIへ比重を置く」という基本思想に加え、AI系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、機体ハードの余裕は平均的になりやすく、AIだけ伸ばしても土台の弱さは補えない。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
