    "legacyRefit": true,
    "summary": "適応・改修系列。初期状態を完成形とせず、弱点補強や運用変更を受け止められる余白を骨格と制御に残す。初期値だけを見ると平凡になりやすいが、育成と改修の方向を後から選びやすい",
    "concept": "ベテルギウスは適応・改修系列。初期状態を完成形とせず、弱点補強や運用変更を受け止められる余白を骨格と制御に残す。初期値だけを見ると平凡になりやすいが、育成と改修の方向を後から選びやすい。ソルベルグ・エンジニアリングの初期設計群の中では「適応・改修系列 / 専門化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ベテルギウス」の名称は、天体名を軌道・周期・光度のように予測可能な挙動モデルへ対応させるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "大量の仮想試験から設計を絞り、実機がモデルから外れにくい系列を基準として整備した。ベテルギウスはその中で適応・改修系列を担当し、最高値ではなく性能分布まで予測できることを品質とみなし、シミュレーションで設計域を決めるというソルベルグ・エンジニアリングの企業思想を、初期状態を完成形とせず、弱点補強や運用変更を受け止められる余白を骨格と制御に残すという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、初期状態を完成形とせず、弱点補強や運用変更を受け止められる余白を骨格と制御に残すこと。「一部特化を避け、複数の条件で最低性能を落としにくい設計」という基本思想に加え、AI系を系列固有の署名として一段強めている。反対に演算系には意図的な余裕不足を残し、初期値だけを見ると平凡になりやすいが、育成と改修の方向を後から選びやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
