    "namingConcept": "「プロキオン」の名称は、天体名を軌道・周期・光度のように予測可能な挙動モデルへ対応させるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "大量の仮想試験から設計を絞り、実機がモデルから外れにくい系列を基準として整備した。プロキオンはその中で複合射撃系列を担当し、最高値ではなく性能分布まで予測できることを品質とみなし、シミュレーションで設計域を決めるというソルベルグ・エンジニアリングの企業思想を、複数の遠距離兵装を切り替えても照準系と姿勢制御を共有できるよう統合するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、複数の遠距離兵装を切り替えても照準系と姿勢制御を共有できるよう統合すること。「実弾・エネルギー双方の射撃兵装へ対応する汎用射撃設計」という基本思想に加え、センサー系を系列固有の署名として一段強めている。反対に機関系には意図的な余裕不足を残し、一種類へ専用化した機体ほどのピークは持たないが、相手に合わせて兵装を変えやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
