    "concept": "レグルスは基幹汎用系列。一つの能力で勝つのではなく、出力・駆動・制御・機関・情報系の接続を崩さないことを優先する。極端な相手へ一点で競るのは苦手だが、育成方針を途中で変えても破綻しにくい。ソルベルグ・エンジニアリングの初期設計群の中では「基幹汎用系列 / 専門化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「レグルス」の名称は、天体名を軌道・周期・光度のように予測可能な挙動モデルへ対応させるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "大量の仮想試験から設計を絞り、実機がモデルから外れにくい系列を基準として整備した。レグルスはその中で基幹汎用系列を担当し、最高値ではなく性能分布まで予測できることを品質とみなし、シミュレーションで設計域を決めるというソルベルグ・エンジニアリングの企業思想を、一つの能力で勝つのではなく、出力・駆動・制御・機関・情報系の接続を崩さないことを優先するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、一つの能力で勝つのではなく、出力・駆動・制御・機関・情報系の接続を崩さないことを優先すること。「突出より総合完成度を優先する汎用設計」という基本思想に加え、機関系を系列固有の署名として一段強めている。反対に駆動系には意図的な余裕不足を残し、極端な相手へ一点で競るのは苦手だが、育成方針を途中で変えても破綻しにくい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、機関系か得意グループを軸にすると個性が出やすい。カスタムは標準適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装は特に固定されておらず、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "基幹汎用系列 / 専門化群",
