    "id": "solberg-castor",
    "legacyRefit": true,
    "summary": "ドローン統合系列。並列処理・通信・状況判断を厚くし、外部ユニットを自機の延長として扱う。本体単独の直接戦闘力は平均的で、演算とAIが育たないと長所が見えにくい",
    "concept": "カストルはドローン統合系列。並列処理・通信・状況判断を厚くし、外部ユニットを自機の延長として扱う。本体単独の直接戦闘力は平均的で、演算とAIが育たないと長所が見えにくい。ソルベルグ・エンジニアリングの初期設計群の中では「ドローン統合系列 / 専門化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「カストル」の名称は、天体名を軌道・周期・光度のように予測可能な挙動モデルへ対応させるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "大量の仮想試験から設計を絞り、実機がモデルから外れにくい系列を基準として整備した。カストルはその中でドローン統合系列を担当し、最高値ではなく性能分布まで予測できることを品質とみなし、シミュレーションで設計域を決めるというソルベルグ・エンジニアリングの企業思想を、並列処理・通信・状況判断を厚くし、外部ユニットを自機の延長として扱うという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、並列処理・通信・状況判断を厚くし、外部ユニットを自機の延長として扱うこと。「並列処理・AI・制御をドローン群運用へ最適化する」という基本思想に加え、AI系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、本体単独の直接戦闘力は平均的で、演算とAIが育たないと長所が見えにくい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「晩成」の伸び方を前提に、AI系かドローン兵装を軸にすると個性が出やすい。カスタムは電子改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "ドローン統合系列 / 専門化群",
