    "developmentBackground": "大量の仮想試験から設計を絞り、実機がモデルから外れにくい系列を基準として整備した。ポルックスはその中で高機動系列を担当し、最高値ではなく性能分布まで予測できることを品質とみなし、シミュレーションで設計域を決めるというソルベルグ・エンジニアリングの企業思想を、加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙うという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙うこと。「駆動・反応・制御を重視した高速設計」という基本思想に加え、駆動系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、耐性や持続出力に余裕が少なく、長い消耗戦では得意な速度を維持しにくい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
