    "namingConcept": "「ベラトリクス」の名称は、天体名を軌道・周期・光度のように予測可能な挙動モデルへ対応させるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "大量の仮想試験から設計を絞り、実機がモデルから外れにくい系列を基準として整備した。ベラトリクスはその中で耐環境・生存系列を担当し、最高値ではなく性能分布まで予測できることを品質とみなし、シミュレーションで設計域を決めるというソルベルグ・エンジニアリングの企業思想を、耐性・機関・制御の余裕を積み、苦手条件を踏んでも性能崩壊しにくくするという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、耐性・機関・制御の余裕を積み、苦手条件を踏んでも性能崩壊しにくくすること。「耐性・機関・制御の余裕を高め、不得意条件で崩れにくくする」という基本思想に加え、機関系を系列固有の署名として一段強めている。反対にセンサー系には意図的な余裕不足を残し、攻撃能力への直接投資が少なく、勝ち筋を作るには兵装適性か出力を後から伸ばしたい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
