    "developmentBackground": "量産ラインごとの差を潰すために系列ごとの製造許容差を厳密に設定し、再現性を商品にした。サイクロンはその中で耐環境・生存系列を担当し、一台の傑作より千台の同品質を優先し、工程の安定性まで設計の一部とするというグレイソン・マニュファクチャリングの企業思想を、耐性・機関・制御の余裕を積み、苦手条件を踏んでも性能崩壊しにくくするという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、耐性・機関・制御の余裕を積み、苦手条件を踏んでも性能崩壊しにくくすること。「耐性・機関・制御の余裕を高め、不得意条件で崩れにくくする」という基本思想に加え、機関系を系列固有の署名として一段強めている。反対に演算系には意図的な余裕不足を残し、攻撃能力への直接投資が少なく、勝ち筋を作るには兵装適性か出力を後から伸ばしたい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、機関系か得意グループを軸にすると個性が出やすい。カスタムは構造改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はレーザー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "耐環境・生存系列 / 初期主力群",
