    "namingConcept": "「テンペスト」の名称は、気象現象名を、変化の大きさではなく大量生産時にも再現できる挙動パターンとして扱うという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "量産ラインごとの差を潰すために系列ごとの製造許容差を厳密に設定し、再現性を商品にした。テンペストはその中で実体弾射撃系列を担当し、一台の傑作より千台の同品質を優先し、工程の安定性まで設計の一部とするというグレイソン・マニュファクチャリングの企業思想を、反動処理・追跡・装備制御をまとめ、実体弾兵装の命中と連続射撃を崩さないよう設計するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、反動処理・追跡・装備制御をまとめ、実体弾兵装の命中と連続射撃を崩さないよう設計すること。「実弾射撃の精度・制御・追跡を安定させる設計」という基本思想に加え、センサー系を系列固有の署名として一段強めている。反対に機関系には意図的な余裕不足を残し、近接へ踏み込まれると設計余力を使いにくく、駆動や耐性の補強が課題になりやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
