    "developmentBackground": "量産ラインごとの差を潰すために系列ごとの製造許容差を厳密に設定し、再現性を商品にした。トルネードはその中で誘導兵装系列を担当し、一台の傑作より千台の同品質を優先し、工程の安定性まで設計の一部とするというグレイソン・マニュファクチャリングの企業思想を、追跡・演算・AI判断を連携させ、ミサイルの誘導と発射判断を機体システム全体で支えるという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、追跡・演算・AI判断を連携させ、ミサイルの誘導と発射判断を機体システム全体で支えること。「追跡・演算・AIを連携させ、ミサイル運用へ寄せる」という基本思想に加え、センサー系を系列固有の署名として一段強めている。反対に機関系には意図的な余裕不足を残し、誘導系へ資源を割くぶん近接時の直接出力は伸びにくい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「中盤型」の伸び方を前提に、センサー系かミサイル兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
