    "legacyRefit": true,
    "summary": "高機動系列。加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙う。耐性や持続出力に余裕が少なく、長い消耗戦では得意な速度を維持しにくい",
    "concept": "ゲイルは高機動系列。加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙う。耐性や持続出力に余裕が少なく、長い消耗戦では得意な速度を維持しにくい。グレイソン・マニュファクチャリングの初期設計群の中では「高機動系列 / 用途分化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ゲイル」の名称は、気象現象名を、変化の大きさではなく大量生産時にも再現できる挙動パターンとして扱うという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "量産ラインごとの差を潰すために系列ごとの製造許容差を厳密に設定し、再現性を商品にした。ゲイルはその中で高機動系列を担当し、一台の傑作より千台の同品質を優先し、工程の安定性まで設計の一部とするというグレイソン・マニュファクチャリングの企業思想を、加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙うという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙うこと。「駆動・反応・制御を重視した高速設計」という基本思想に加え、駆動系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、耐性や持続出力に余裕が少なく、長い消耗戦では得意な速度を維持しにくい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
