    "namingConcept": "「オーロラ」の名称は、気象現象名を、変化の大きさではなく大量生産時にも再現できる挙動パターンとして扱うという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "量産ラインごとの差を潰すために系列ごとの製造許容差を厳密に設定し、再現性を商品にした。オーロラはその中でドローン統合系列を担当し、一台の傑作より千台の同品質を優先し、工程の安定性まで設計の一部とするというグレイソン・マニュファクチャリングの企業思想を、並列処理・通信・状況判断を厚くし、外部ユニットを自機の延長として扱うという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、並列処理・通信・状況判断を厚くし、外部ユニットを自機の延長として扱うこと。「並列処理・AI・制御をドローン群運用へ最適化する」という基本思想に加え、演算系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、本体単独の直接戦闘力は平均的で、演算とAIが育たないと長所が見えにくい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「晩成」の伸び方を前提に、演算系かドローン兵装を軸にすると個性が出やすい。カスタムは電子改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
