    "concept": "ベイズは演算中枢系列。並列処理・情報統合・演算効率を厚くし、複数の判断やセンサー情報を同時に処理する。演算能力が高くても駆動や機関が追いつかなければ結果へ変換できず、育成の噛み合わせが重要。ラプラス機関の初期設計群の中では「演算中枢系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ベイズ」の名称は、数学・統計の名称を予測・推定・変換・最適化といった演算手順そのものへ対応させるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
