    "engineeringNotes": "設計の中心は、探知・妨害・演算・AIを一つの電子戦ループにまとめ、相手の判断環境そのものを悪化させること。「EMP・ドローン・誘導兵装を横断する情報戦向け設計」という基本思想に加え、演算系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、電子系への依存が大きく、出力・耐性の正面勝負では補強が必要。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「中盤型」の伸び方を前提に、演算系かEMP・ドローン・ミサイル兵装を軸にすると個性が出やすい。カスタムは電子改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
