    "concept": "エントロピーは精密制御系列。兵装と機体運動を細かく同期させ、数値以上に「狙った動作を外さない」ことを重視する。粗い高出力運用には向かず、強みを活かすには制御・精度系を伸ばす育成が必要になる。ラプラス機関の初期設計群の中では「精密制御系列 / 用途分化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
