    "developmentBackground": "戦闘を数理モデルへ落とし込む初期実証群で、各系列が異なる予測手法を機体構成へ反映する。エントロピーはその中で精密制御系列を担当し、十分な情報を集め、結果を確率ではなく予測可能な現象へ近づけるというラプラス機関の企業思想を、兵装と機体運動を細かく同期させ、数値以上に「狙った動作を外さない」ことを重視するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
