    "developmentBackground": "戦闘を数理モデルへ落とし込む初期実証群で、各系列が異なる予測手法を機体構成へ反映する。アトラクタはその中で高機動系列を担当し、十分な情報を集め、結果を確率ではなく予測可能な現象へ近づけるというラプラス機関の企業思想を、加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙うという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、加速・反応・姿勢遷移を短い時間でつなぎ、先に有利な状態へ入ることを狙うこと。「駆動・反応・制御を重視した高速設計」という基本思想に加え、駆動系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、耐性や持続出力に余裕が少なく、長い消耗戦では得意な速度を維持しにくい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「早熟」の伸び方を前提に、駆動系かブレード・ランス・ビームブレード兵装を軸にすると個性が出やすい。カスタムは高モジュール適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はキャノン・ビームキャノン、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "高機動系列 / 専門化群",
