    "concept": "オービットは機関余力系列。発電・供給・冷却・熱容量を厚くし、他の性能が負荷で落ちない土台を作る。直接勝敗へ見えにくい能力へ資源を使うため、初見では総合評価以上に地味に映りやすい。ラプラス機関の初期設計群の中では「機関余力系列 / 専門化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「オービット」の名称は、数学・統計の名称を予測・推定・変換・最適化といった演算手順そのものへ対応させるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "戦闘を数理モデルへ落とし込む初期実証群で、各系列が異なる予測手法を機体構成へ反映する。オービットはその中で機関余力系列を担当し、十分な情報を集め、結果を確率ではなく予測可能な現象へ近づけるというラプラス機関の企業思想を、発電・供給・冷却・熱容量を厚くし、他の性能が負荷で落ちない土台を作るという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、発電・供給・冷却・熱容量を厚くし、他の性能が負荷で落ちない土台を作ること。「発電・供給・冷却に余裕を持たせ、兵装の土台を強くする」という基本思想に加え、機関系を系列固有の署名として一段強めている。反対に駆動系には意図的な余裕不足を残し、直接勝敗へ見えにくい能力へ資源を使うため、初見では総合評価以上に地味に映りやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、機関系かビームキャノン・レーザー・キャノン兵装を軸にすると個性が出やすい。カスタムは構造改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はドローン、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
