    "engineeringNotes": "設計の中心は、近接運動と高密度電力供給を同期させ、ビームブレードの出力を動作中も維持すること。「ビームブレード運用を軸に出力・制御・機関を高める」という基本思想に加え、制御系を系列固有の署名として一段強めている。反対にAI系には意図的な余裕不足を残し、機関・制御・駆動を同時に要求するため、どこか一つが遅れると完成度が落ちやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「中盤型」の伸び方を前提に、制御系かビームブレード兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はキャノン、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
