    "concept": "プレディクタは高出力系列。瞬間出力と過負荷領域を積極的に使い、短時間で能力差を作ることを狙う。熱・信頼性・持続性との交換が明確で、扱いを誤ると数値ほど安定して勝てない。ラプラス機関の初期設計群の中では「高出力系列 / 初期技術展開群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
