    "developmentBackground": "互いに共通規格すら少ない初期案件群で、CASEごとに全く異なる発注条件を満たすためだけに作られた。ケース20はその中で基幹汎用系列を担当し、目的に不要な一貫性を持たず、依頼ごとに最短で要求値へ到達するという第十三技術局の企業思想を、一つの能力で勝つのではなく、出力・駆動・制御・機関・情報系の接続を崩さないことを優先するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、一つの能力で勝つのではなく、出力・駆動・制御・機関・情報系の接続を崩さないことを優先すること。「突出より総合完成度を優先する汎用設計」という基本思想に加え、制御系を系列固有の署名として一段強めている。反対に演算系には意図的な余裕不足を残し、極端な相手へ一点で競るのは苦手だが、育成方針を途中で変えても破綻しにくい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、制御系か得意グループを軸にすると個性が出やすい。カスタムは標準適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装は特に固定されておらず、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "基幹汎用系列 / 初期技術展開群",
