    "legacyRefit": true,
    "summary": "実験・変動系列。平均値より成功時の突出を重視し、個体差や未成熟技術を意図的に残す。当たり個体は強烈だが再現性が低く、同じ系列名でも育成方針が毎回変わりやすい",
    "concept": "ファントムは実験・変動系列。平均値より成功時の突出を重視し、個体差や未成熟技術を意図的に残す。当たり個体は強烈だが再現性が低く、同じ系列名でも育成方針が毎回変わりやすい。エイドロン研究所の初期設計群の中では「実験・変動系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ファントム」の名称は、幻影・記憶・人格を示す名称を、同一設計から生まれる個体差や学習差の観測テーマへ対応させるという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "個体差研究の基礎群として、意図的に均質化しない部位を系列ごとに変えている。ファントムはその中で実験・変動系列を担当し、ばらつきを欠陥として消すのではなく、どの差が強さへ変わるかを観測するというエイドロン研究所の企業思想を、平均値より成功時の突出を重視し、個体差や未成熟技術を意図的に残すという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、平均値より成功時の突出を重視し、個体差や未成熟技術を意図的に残すこと。「大きな長所と欠点を同居させる試験色の強い設計」という基本思想に加え、駆動系を系列固有の署名として一段強めている。反対に制御系には意図的な余裕不足を残し、当たり個体は強烈だが再現性が低く、同じ系列名でも育成方針が毎回変わりやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「中盤型」の伸び方を前提に、駆動系かビームキャノン・EMP・ドローン兵装を軸にすると個性が出やすい。カスタムは試供品適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装は特に固定されておらず、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
