    "summary": "高信頼標準系列。設計値に近い性能を毎回出すことを最優先し、信頼性と制御の再現性へ資源を回す。大当たり個体や極端なピーク性能は出にくい代わりに、計画通り育てやすい",
    "concept": "ホロウは高信頼標準系列。設計値に近い性能を毎回出すことを最優先し、信頼性と制御の再現性へ資源を回す。大当たり個体や極端なピーク性能は出にくい代わりに、計画通り育てやすい。エイドロン研究所の初期設計群の中では「高信頼標準系列 / 初期技術展開群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
