    "developmentBackground": "個体差研究の基礎群として、意図的に均質化しない部位を系列ごとに変えている。ホロウはその中で高信頼標準系列を担当し、ばらつきを欠陥として消すのではなく、どの差が強さへ変わるかを観測するというエイドロン研究所の企業思想を、設計値に近い性能を毎回出すことを最優先し、信頼性と制御の再現性へ資源を回すという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、設計値に近い性能を毎回出すことを最優先し、信頼性と制御の再現性へ資源を回すこと。「性能の再現性と安定稼働を最優先する堅実設計」という基本思想に加え、制御系を系列固有の署名として一段強めている。反対にセンサー系には意図的な余裕不足を残し、大当たり個体や極端なピーク性能は出にくい代わりに、計画通り育てやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
