    "concept": "アクシオムは実験・変動系列。平均値より成功時の突出を重視し、個体差や未成熟技術を意図的に残す。当たり個体は強烈だが再現性が低く、同じ系列名でも育成方針が毎回変わりやすい。LOGOSの初期設計群の中では「実験・変動系列 / 初期主力群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「アクシオム」の名称は、哲学語を名称に使うが、語義と機体性能の対応規則は公式には説明されないという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "出所の異なる機体群に見える一方、分解すると同じ設計判断が繰り返されている初期確認群。アクシオムはその中で実験・変動系列を担当し、外部からは思想不明だが、異なる系列にも同じ数理的・構造的規則が断片的に観測されるというLOGOSの企業思想を、平均値より成功時の突出を重視し、個体差や未成熟技術を意図的に残すという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、平均値より成功時の突出を重視し、個体差や未成熟技術を意図的に残すこと。「大きな長所と欠点を同居させる試験色の強い設計」という基本思想に加え、駆動系を系列固有の署名として一段強めている。反対に機関系には意図的な余裕不足を残し、当たり個体は強烈だが再現性が低く、同じ系列名でも育成方針が毎回変わりやすい。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
