    "concept": "ソフィアは複合近接系列。近接兵装の切替と姿勢遷移を一つの動作体系にまとめ、間合いの変化へ追従する。単一武器へ特化した系列より最大値は低いが、兵装変更を含む育成自由度が高い。LOGOSの初期設計群の中では「複合近接系列 / 専門化群」に位置づけられ、後続系列へ繋がる基準機として、得意分野だけでなく意図的に残した弱点まで明確に設計されている。",
    "namingConcept": "「ソフィア」の名称は、哲学語を名称に使うが、語義と機体性能の対応規則は公式には説明されないという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "出所の異なる機体群に見える一方、分解すると同じ設計判断が繰り返されている初期確認群。ソフィアはその中で複合近接系列を担当し、外部からは思想不明だが、異なる系列にも同じ数理的・構造的規則が断片的に観測されるというLOGOSの企業思想を、近接兵装の切替と姿勢遷移を一つの動作体系にまとめ、間合いの変化へ追従するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、近接兵装の切替と姿勢遷移を一つの動作体系にまとめ、間合いの変化へ追従すること。「近接兵装を選ばず扱えるよう駆動・制御・出力を均衡させる」という基本思想に加え、駆動系を系列固有の署名として一段強めている。反対に機関系には意図的な余裕不足を残し、単一武器へ特化した系列より最大値は低いが、兵装変更を含む育成自由度が高い。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「中盤型」の伸び方を前提に、駆動系かブレード・ハンマー・ランス・ビームブレード兵装を軸にすると個性が出やすい。カスタムは兵装改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はキャノン、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "複合近接系列 / 専門化群",
