    "developmentBackground": "出所の異なる機体群に見える一方、分解すると同じ設計判断が繰り返されている初期確認群。ヌースはその中で複合射撃系列を担当し、外部からは思想不明だが、異なる系列にも同じ数理的・構造的規則が断片的に観測されるというLOGOSの企業思想を、複数の遠距離兵装を切り替えても照準系と姿勢制御を共有できるよう統合するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
