    "namingConcept": "「メトロン」の名称は、哲学語を名称に使うが、語義と機体性能の対応規則は公式には説明されないという命名規則に基づく。単なる愛称ではなく、設計チームが何を優先するかを共有する短い設計言語として扱われている。",
    "developmentBackground": "出所の異なる機体群に見える一方、分解すると同じ設計判断が繰り返されている初期確認群。メトロンはその中で精密制御系列を担当し、外部からは思想不明だが、異なる系列にも同じ数理的・構造的規則が断片的に観測されるというLOGOSの企業思想を、兵装と機体運動を細かく同期させ、数値以上に「狙った動作を外さない」ことを重視するという形で具体化した。初期世代ながら後続機の基準になった要素が多く、同社の系列史を読むうえで基準点になりやすい。",
    "engineeringNotes": "設計の中心は、兵装と機体運動を細かく同期させ、数値以上に「狙った動作を外さない」ことを重視すること。「姿勢・装備・微細制御を軸に、武装を正確に扱う設計」という基本思想に加え、制御系を系列固有の署名として一段強めている。反対に出力系には意図的な余裕不足を残し、粗い高出力運用には向かず、強みを活かすには制御・精度系を伸ばす育成が必要になる。数値の平均より、強みと弱みの組み合わせが明確に出るよう再整理された系列である。",
    "trainingNotes": "育成では「均等成長」の伸び方を前提に、制御系かライフル・レーザー・ランス兵装を軸にすると個性が出やすい。カスタムは精密改修適合との相性を重視し、弱点を全部消すより一つの得意分野を明確に伸ばす方が系列思想を活かしやすい。非推奨兵装はハンマー、別路線へ育てる場合は機体側の基礎能力との噛み合わせを見る必要がある。",
    "marketPosition": "精密制御系列 / 初期技術展開群",
